addStyle=()=>{if(this.isInit)return;const t=document.createElement("style");t.innerHTML='#tooltip-id {
        position: fixed;
        width: 290px;
        height: 220px;
        z-index: 99999;
        top: 0;
        left: 0;
        display: flex;
        flex-direction: column;
        background-color: #111;
        align-items: center;
        border-radius: 5px;
        border: 1px solid #5d5d5d;
        font-size: 14px;
        visibility: hidden;
        color: #ccc;
        font-family: 'Roboto', sans-serif;
    }

    #tooltip-id.show {
        visibility: visible;
    }

    #tooltip-id .tooltip-image {
        margin: 30px 0 30px;
        height: 100px;
        background-repeat: no-repeat;
        background-size: contain;
        object-fit: cover;
        object-position: center;
    }

    #tooltip-id .tooltip-title {
        width: calc(100% - 40px);
        margin-bottom: 7px;
        font-size: 14px;
        text-transform: uppercase;
        text-align: center;
    }

    #tooltip-id #tooltip-status {
        width: calc(100% - 40px);
        display: flex;
    }

    .low-batt{
      color: #c8323c;
    }

    #tooltip-id .status-icon {
        width: 14px;
        height: 14px;
        background-repeat: no-repeat;
        background-size: contain;
        margin-right: 5px;
    }

    #tooltip-id .batt {
        position: absolute;
        right: 10px;
        top: 10px;
        display: flex;
        justify-content: center;
        align-items: center;
    }

    #tooltip-id .batt .batt-icon {
        background-position: 50%;
        background-repeat: no-repeat;
        background-size: 20px;
        height: 26px;
        width: 26px;
    }
    #tooltip-id.device-type.loading::before{
      content: '';
      position: absolute;
      z-index: 1;
      top: 65px;
      left: 50%;
      width: 30px;
      height: 30px;
      margin-left: -15px;
      background-repeat: no-repeat;
      background-size: contain;
