      animation: spin 1s linear infinite;
    }

    #tooltip-id.device-type .tooltip-image {
        margin: 10px 0 0 0;
        height: 140px;
    }

    #tooltip-id.device-type .tooltip-title {
        text-align: center;
        margin-bottom: 0;
        line-height: 16px;
    }

    #tooltip-id.device-type #tooltip-status {
        justify-content: center;
        line-height: 16px;
    }

    #tooltip-id.device-type .status-text {
        font-size: 12px;
        color: rgba(68, 214, 44, 1);
    }

    #tooltip-id.device-type .status-icon {
        display: none;
    }

    #tooltip-id.synapse {
        width: auto;
        height: auto;
    }

    #tooltip-id.synapse * {
        display: none;
    }

    #tooltip-id.synapse .tooltip-title {
        display: block;
        width: auto;
        margin: 10px;
    }
    @keyframes spin {
      from {
        transform: rotate(0deg);
      }
      to {
        transform: rotate(360deg);
      }
    }
